def materials_for_species(species):
    """Valid MATERIAL options for a SPECIES (exact match first, then case-insensitive)."""
    if species is None:
        return []
    if species in DATE_BASE:
        return DATE_BASE[species]
    for key, value in DATE_BASE.items():
        if key.lower() == species.lower():
            return value
    return []
